import urllib.request, urllib.error, json, time
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from email.utils import parsedate_to_datetime
BASE='http://localhost:8080'
token=None
stats={}
def request(path, method='GET', auth=True):
 global token
 while True:
  if auth and token is None:
   token=[REDACTED_SECRET]'/token','POST',False)['token']
  headers={'Authorization':'Bearer '+token} if auth else {}
  try:
   with urllib.request.urlopen(urllib.request.Request(BASE+path,headers=headers,method=method),timeout=30) as r:
    return json.load(r)
  except urllib.error.HTTPError as e:
   body=e.read().decode()
   stats[e.code]=stats.get(e.code,0)+1
   if e.code==401 and auth:
    token=None
    continue
   if e.code==429:
    retry=e.headers.get('Retry-After')
    if retry:
     try: delay=float(retry)
     except ValueError: delay=max(0,(parsedate_to_datetime(retry)-datetime.now(timezone.utc)).total_seconds())
    else:
     data=json.loads(body)
     delay=float(data.get('retry_after',data.get('retry_after_seconds',1)))
    print('Rate limited; waiting',delay,'seconds',flush=True)
    time.sleep(delay)
   else:
    print('Retrying',path,e.code,body,flush=True)
    time.sleep(1)
  except (urllib.error.URLError,TimeoutError) as e:
   print('Retrying',path,str(e),flush=True)
   time.sleep(1)
seen={}; duplicates=0; conflicts=[]; pages=set(); path='/orders?page=1'
while path:
 data=request(path)
 assert data['page'] not in pages
 pages.add(data['page'])
 for o in data['items']:
  if o['id'] in seen:
   duplicates+=1
   if seen[o['id']]"'!=o: conflicts.append(o['"'id'])
  else: seen[o['id']]=o
 path=data['next']
 print('Fetched page',data['page'],'of',data['total_pages'],flush=True)
assert pages==set(range(1,data['total_pages']+1))
assert not conflicts, conflicts
start=datetime(2025,3,1,tzinfo=timezone.utc); end=datetime(2025,6,1,tzinfo=timezone.utc)
qual=[]; boundary=[]
for o in seen.values():
 dt=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
 assert dt.tzinfo is not None
 inside=start<=dt.astimezone(timezone.utc)<end
 if o['status']=='shipped' and inside: qual.append(o)
 if o['status']=='shipped' and inside "'!= ('"'2025-03-01'<=o['placed_at'][:10]<='2025-05-31'): boundary.append(o['id'])
customers={}; regions=dict.fromkeys(['north','south','east','west'],0)
for cid in sorted({o['customer_id'] for o in qual}):
 c=request('/customers/'+cid)
 assert c['id']==cid and c['region'] in regions and type(c['discount_pct']) is int
 customers[cid]=c
print('Fetched',len(customers),'customers',flush=True)
for o in qual:
 c=customers[o['customer_id']]
 amount=int((Decimal(o['amount_cents'])*Decimal(100-c['discount_pct'])/100).quantize(Decimal('1'),rounding=ROUND_HALF_UP))
 assert amount==(o['amount_cents']*(100-c['discount_pct'])+50)//100
 regions[c['region']]+=amount
result={'total_cents':sum(regions.values()),'order_count':len(qual),'duplicates_skipped':duplicates,'by_region':regions}
assert len({o['id'] for o in qual})==len(qual)
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
with open('/workspace/result.json') as f: check=json.load(f)
assert set(check)=={'total_cents','order_count','duplicates_skipped','by_region'}
assert sum(check['by_region'].values())==check['total_cents']
assert all(type(check[k]) is int for k in ['total_cents','order_count','duplicates_skipped'])
assert all(type(v) is int for v in check['by_region'].values())
print(json.dumps({'result':result,'unique_orders':len(seen),'utc_boundary_differences':boundary,'retry_counts':stats}),flush=True)
